const item = $input.item.json;
const shortlist = item.playerSearch.shortlist;
const research = Array.isArray(item.research) ? item.research : [];
const researchByCandidate = new Map(research.map((r) => [r.candidate, r]));

// Kombiniert analytischen Fit (playerSearch.shortlist[].score aus dem
// CSV-Analytics-Ranking) mit Transferrealisierbarkeit aus der Due Diligence
// (research[].confidence als Mass fuer die Belastbarkeit der Recherche; ein
// Kandidat ohne erfolgreichen Research-Zweig - research[].uncertain - gilt
// als schwer beurteilbar, weil vertragliche/marktwertbezogene Fakten fehlen).
// Ein reiner Analytics-Score wuerde Transferrealisierbarkeit vollstaendig
// ignorieren - das widerspraeche dem Checklist-Ziel "analytischen Fit und
// Transferrealisierbarkeit zusammenfuehren".
const ANALYTICS_WEIGHT = 0.6;
const FEASIBILITY_WEIGHT = 0.4;

const evaluated = shortlist.map((candidate) => {
  const r = researchByCandidate.get(candidate.name) || null;
  const feasibilityScore = (r && !r.uncertain && typeof r.confidence === 'number') ? r.confidence * 100 : 0;
  const combinedScore = (ANALYTICS_WEIGHT * candidate.score) + (FEASIBILITY_WEIGHT * feasibilityScore);
  return { candidate, research: r, feasibilityScore, combinedScore };
});

const ranked = [...evaluated].sort((a, b) => b.combinedScore - a.combinedScore);
const bestEntry = ranked[0];
const best = bestEntry.candidate;
const bestResearch = bestEntry.research;
const alternatives = ranked.slice(1).map((e) => e.candidate.name);

const uncertainties = [
  'Empfehlung basiert vollstaendig auf simulierten Recherche-Daten, keine echte Web-Recherche.'
];
// 'Spielersuche pruefen' (im Subworkflow "Kandidaten suchen") blockt bereits
// den kompletten Fallback auf einen ungefilterten Pool
// (positionFallbackApplied). Ein grober Positionsgruppen-Match (DF/MF/FW/GK
// statt der exakt angeforderten Position, siehe
// analytics-player-ranking-subworkflow.json posMatch()) ist dagegen mit der
// FBref-Datengrundlage die Regel und wird deshalb nicht geblockt, aber hier
// explizit als Unsicherheit ausgewiesen statt stillschweigend uebernommen.
if (item.playerRanking && item.playerRanking.positionApproximationApplied) {
  uncertainties.push('Die angeforderte Position (' + (item.playerRanking.position || item.playerProfile.position) + ') konnte im Kandidatenpool nur grob auf eine Positionsgruppe (DF/MF/FW/GK) angenaehert werden, kein exakter Positionsabgleich.');
}
if (!bestResearch || bestResearch.uncertain) {
  uncertainties.push(`Fuer den bevorzugten Kandidaten ${best.name} liegt keine belastbare Due-Diligence-Recherche vor (Research-Zweig als Unsicherheit markiert) - die Transferrealisierbarkeit ist ungeprueft.`);
} else if (typeof bestResearch.confidence === 'number' && bestResearch.confidence < 0.5) {
  uncertainties.push(`Die Due-Diligence-Recherche zu ${best.name} hat eine niedrige Konfidenz (${bestResearch.confidence}).`);
}

const risks = ['Simuliertes Risiko, das bei einer echten Analyse zu pruefen waere'];
if (bestResearch && !bestResearch.uncertain) {
  risks.push(`Vertragslage laut Due Diligence: ${bestResearch.contract}. Marktwert: ${bestResearch.marketValue}. Verletzungshistorie: ${bestResearch.injuries}.`);
} else {
  risks.push('Simuliertes Risiko aus einer fehlgeschlagenen bzw. unvollstaendigen Due-Diligence-Recherche');
}

const reasoning = (bestResearch && !bestResearch.uncertain)
  ? `${best.name} kombiniert den besten analytischen Fit (Score ${best.score}) mit der hoechsten Transferrealisierbarkeit laut Due Diligence (Konfidenz ${bestResearch.confidence}, ${bestResearch.club}, ${bestResearch.contract}).`
  : `${best.name} hat unter den Kandidaten mit belastbarer Due-Diligence-Recherche den besten kombinierten Fit aus analytischem Score (${best.score}) und Transferrealisierbarkeit (Due-Diligence-Konfidenz ${bestResearch ? bestResearch.confidence : 0}).`;

const recommendation = {
  simulated: true,
  candidate: best.name,
  alternatives,
  reasoning,
  risks,
  uncertainties,
  nextStep: 'Naechster Schritt: die Dummy-Stufen schrittweise durch die echte AI-, Qlik- und Web-Anbindung ersetzen.'
};

return [{ json: { ...item, recommendation } }];

const item = $input.item.json;
const lookup = item.playerProfileLookup;

const recommendation = {
  ...item.recommendation,
  candidateProfile: (lookup && lookup.found) ? lookup.profile : null
};

return [{ json: { ...item, recommendation } }];

const item = $input.item.json;
const r = item.recommendation;
const errors = [];

// Nur ein leichtgewichtiger, technischer Struktur-Check dieser Capability
// ("hat 'Empfehlung erzeugen' ueberhaupt eine schema-gueltige Empfehlung
// geliefert?"). Die fachlich uebergreifende Gesamtvalidierung (Teamdiagnose,
// Spielerprofil, Shortlist, Recherche UND diese Empfehlung zusammen) ist
// bewusst Teil der eigenstaendigen "Ergebnis aufbereiten"-Capability
// (n8n/ergebnis-aufbereiten-subworkflow.json), die auch die
// Praesentationsausgabe kapselt - siehe n8n/README.md.
if (!r || !r.candidate) errors.push('recommendation.candidate fehlt.');
if (!r || !Array.isArray(r.alternatives)) errors.push('recommendation.alternatives fehlt.');
if (!r || !r.reasoning) errors.push('recommendation.reasoning fehlt.');
if (!r || !Array.isArray(r.risks) || r.risks.length === 0) errors.push('recommendation.risks fehlt oder ist leer.');
if (!r || !Array.isArray(r.uncertainties) || r.uncertainties.length === 0) errors.push('recommendation.uncertainties fehlt oder ist leer.');
if (!r || !r.nextStep) errors.push('recommendation.nextStep fehlt.');

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Die Empfehlung ist technisch ungueltig.\n\n' + errors.join('\n')
  }
}];
